<?php

# @autogenerated
declare(strict_types=1);

use Civi\Lughauth\Features\Access\User\Domain\ValueObject\Accessor\UserUseSecondFactorsAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserUseSecondFactorsAccessor trait.
 *
 * Covers null default, string/VO assignment via withUseSecondFactors,
 * getUseSecondFactors/useSecondFactors accessors, and isUseSecondFactorsChanged with/without original.
 */
class UserUseSecondFactorsAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withUseSecondFactors creates a new instance with the UseSecondFactors set
     * from a string value, and getUseSecondFactors returns the primitive string.
     */
    public function testWithUseSecondFactorsFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserUseSecondFactorsAccessorUnitTest();

        // Act
        $result = $holder->withUseSecondFactors(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->isUseSecondFactors());
    }
    /**
     * Asserts that withuseSecondFactors has access to the value object
     * from a string value, and getUseSecondFactors returns the primitive string.
     */
    public function testWithUseSecondFactorsFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserUseSecondFactorsAccessorUnitTest();

        // Act
        $result = $holder->withUseSecondFactors(true);

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals(true, $result->useSecondFactors()->value());
    }
    public function testChangedUseSecondFactors(): void
    {
        // Arrange
        $holder = new ImplWithUserUseSecondFactorsAccessorUnitTest();
        $original = $holder->withUseSecondFactors(true);
        $same = $holder->withUseSecondFactors(true);
        $modified = $holder->withUseSecondFactors(false);

        // Act
        $unchanged = $holder->isUseSecondFactorsChanged();
        $withSame = $original->isUseSecondFactorsChanged($same);
        $withDiferent = $original->isUseSecondFactorsChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserUseSecondFactorsAccessorUnitTest
{
    use UserUseSecondFactorsAccessor;
}
